parameters.query:
SELECT title, domain, importance, urgency, status, next_action, due_date
FROM v_open_tasks
LIMIT 10;

parameters.jsCode:
const rows = $input.all().map(i => i.json);
const now = new Date();
const overdue = rows.filter(r => r.due_date && new Date(r.due_date) < now).length;
const top = rows.slice(0, 3).map(r => '• ' + r.title + (r.next_action ? ' ← التالي: ' + r.next_action : '')).join('
') || '• لا توجد مهام مفتوحة — يوم نظيف 🎉';
const text = '🌅 **بريف الصباح** — ' + now.toLocaleDateString('ar-SA-u-nu-latn') + '

أهم 3 إجراءات:
' + top + '

مفتوحة: ' + rows.length + ' | متأخرة: ' + overdue + '
التزم بسقف الإنفاق الأسبوعي 2,600 ر.س (مهمة FIN-001).';
return [{ json: { chat_id: $env.TELEGRAM_ADMIN_CHAT_ID || '', text } }];
